    candidates.append(m.group(0))
for m in re.finditer(r'\[.*?\]', text, re.S):
    candidates.append(m.group(0))
link = None
parsed = None
for c in sorted(candidates, key=len, reverse=True):
    try:
        obj = json.loads(c)
    except Exception:
        continue
    parsed = obj
    def find_link(x):
        if isinstance(x, dict):
            if isinstance(x.get('webViewLink'), str) and x['webViewLink'].startswith('http'):
                return x['webViewLink']
            for v in x.values():
                r = find_link(v)
                if r: return r
        elif isinstance(x, list):
            for v in x:
                r = find_link(v)
                if r: return r
        return None
    link = find_link(obj)
    if link:
        break
if not link:
    m = re.search(r'https://docs\.google\.com/[^\s)\]>]+|https://drive\.google\.com/[^\s)\]>]+', text)
    if m:
        link = m.group(0)
if not link:
    print('PUBLISH_INVALID: No Google Drive link found')
    sys.exit(1)
print('PUBLISH_LINK:', link)
